import java.util.*;

class Solution {
  public int nextBeautifulNumber(int n) {
    for (int x = n + 1; ; x++) {
      int[] c = new int[10];
      int y = x;
      while (y > 0) {
        c[y % 10]++;
        y /= 10;
      }
      boolean ok = true;
      for (int i = 0; i < 10; i++)
        if (c[i] != 0 && c[i] != i) {
          ok = false;
          break;
        }
      if (ok) return x;
    }
  }
}
